import { test, expect, vi } from 'vitest';
import { cache, getQuote, isFreshToken } from '../src/quotes';

test('caches the first quote', async () => {
  vi.spyOn(global, 'fetch').mockResolvedValue({ ok: true, json: async () => ({ q: 'hi' }) } as Response);
  await getQuote();           // заполняет модульный `cache`
  expect(cache.size).toBe(1);
});

test('second call hits cache, not network', async () => {
  await getQuote();
  expect(cache.size).toBe(1); // предполагает, что ПЕРВЫЙ тест прошёл раньше
});

test('token minted now is fresh', () => {
  expect(isFreshToken({ mintedAt: Date.now() })).toBe(true); // реальные часы
});
